from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..validators import IsString
from ..converter import to_float


class TiltManagement(BaseInterface):
    def configure_tilt(self, target_dist_name, device_data=None, tilt_angle=None, min_angle=None, max_angle=None,
                       timeout=120, alias="default"):
        """ Configure Tilt

        :param string target_dist_name: target dist name - mandatory parameter
                                        Possible distnames available in:
                                        http://cebula.emea.nsn-net.net:8888/spec/admin-spec/wikis/admin-api-tilt-mgmt
        :param string device_data: deviceData (optional)
        :param float tilt_angle: mechanicalTiltAngle (optional)
        :param float min_angle: minTiltAngle (optional)
        :param float max_angle: maxTiltAngle (optional)
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_dist_name)
        parameters = {"targetDN": target_dist_name}
        if device_data is not None:
            IsString().check(device_data)
            parameters["deviceData"] = device_data
        if tilt_angle is not None:
            tilt_angle = to_float(tilt_angle)
            parameters["mechanicalTiltAngle"] = tilt_angle
        if min_angle is not None:
            min_angle = to_float(min_angle)
            parameters["minTiltAngle"] = min_angle
        if max_angle is not None:
            max_angle = to_float(max_angle)
            parameters["maxTiltAngle"] = max_angle

        self.store.get(alias).execute_procedure("configureTilt", parameters, timeout)

    def set_tilt_angle(self, target_dist_name, angle, timeout=120, alias="default"):
        """ Configure Tilt

        :param string target_dist_name: target dist name
                                        Possible distnames available in:
                                        http://cebula.emea.nsn-net.net:8888/spec/admin-spec/wikis/admin-api-tilt-mgmt
        :param float angle: angle
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_dist_name)
        angle = to_float(angle)

        self.store.get(alias).execute_procedure("setTiltAngle", {"targetDN": target_dist_name, "id": target_dist_name, "angle": angle}, timeout)

    def calibrate_tilt(self, target_dist_name, timeout=120, alias="default"):
        """ Configure Tilt

        :param string target_dist_name: target dist name
                                        Possible distnames available in:
                                        http://cebula.emea.nsn-net.net:8888/spec/admin-spec/wikis/admin-api-tilt-mgmt
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_dist_name)

        self.store.get(alias).execute_procedure("calibrateTilt", {"targetDN": target_dist_name, "id": target_dist_name}, timeout)
